package com.alzhefi
import android.content.Intent
import android.os.Build
import com.facebook.react.bridge.*
class LocationTrackingModule(private val context:ReactApplicationContext):ReactContextBaseJavaModule(context){
 override fun getName()="LocationTracking"
 @ReactMethod fun start(owner:String,role:String,token:String,promise:Promise){try{if(currentActivity==null){promise.reject("NOT_VISIBLE","Open AlzheFi to start tracking.");return};if(owner.isBlank()||token.isBlank()||role !in listOf("patient","caregiver")){promise.reject("INVALID_SESSION","Check the signed-in account.");return};LocationTrackingService.epoch++;TrackingStore.save(context,owner,role,token);val i=Intent(context,LocationTrackingService::class.java);if(Build.VERSION.SDK_INT>=26)context.startForegroundService(i)else context.startService(i);promise.resolve(true)}catch(_:Exception){TrackingStore.clear(context);promise.reject("START_FAILED","Native tracking could not start.")}}
 @ReactMethod fun stop(promise:Promise){LocationTrackingService.epoch++;TrackingStore.clear(context);context.stopService(Intent(context,LocationTrackingService::class.java));promise.resolve(true)}
 @ReactMethod fun status(promise:Promise){val now=System.currentTimeMillis();val map=Arguments.createMap();map.putBoolean("running",LocationTrackingService.running);map.putDouble("lastFixReceived",LocationTrackingService.lastFixReceived.toDouble());map.putDouble("lastFixRecorded",LocationTrackingService.lastFixRecorded.toDouble());map.putDouble("lastSent",LocationTrackingService.lastSent.toDouble());val age=now-LocationTrackingService.lastFixReceived;val sentAge=now-LocationTrackingService.lastSent;map.putString("issue",when{!LocationTrackingService.running->"Tracking is not running. Open this screen to check sharing and restart.";LocationTrackingService.lastFixReceived==0L->LocationTrackingService.issue;age>=60000->"No new native GPS callback for "+age/1000+"s. Tracking may be interrupted.";LocationTrackingService.issue.isNotBlank()->LocationTrackingService.issue;else->"Native GPS callback "+age/1000+"s ago. Last successful send "+sentAge/1000+"s ago."});promise.resolve(map)}
}
